css:
:root { color: rgb(40, 35, 30); font-synthesis: none; text-rendering: optimizelegibility; -webkit-font-smoothing: antialiased; background: rgb(243, 239, 231); font-family: Georgia, "Times New Roman", serif; }
* { box-sizing: border-box; }
body { min-width: min(20rem, 100%); min-height: 100vh; margin: 0px; }
.document-header { min-width: 0px; margin: 0.75rem 0px 0.5rem; }
.document-header__main { align-items: center; gap: 0.5rem 1rem; display: flex; }
.document-header__identity { flex: 1 1 0%; min-width: 0px; }
.chant-editor .document-header__title { text-align: left; margin: 0px; font-size: clamp(1.3rem, 3vw, 1.75rem); }
.chant-editor .document-header__title-button { text-align: left; overflow-wrap: anywhere; background: 0px 0px; border-color: rgba(0, 0, 0, 0); align-items: baseline; gap: 0.4rem; max-width: 100%; min-height: 2.25rem; padding: 0.15rem 0px; display: inline-flex; }
.document-header__edit-icon { color: rgb(103, 95, 85); font-size: 0.8rem; }
.document-header__title-input { box-sizing: border-box; color: rgb(40, 35, 30); width: 100%; min-width: 0px; min-height: 2.25rem; font: inherit; background: rgb(255, 253, 248); border: 1px solid rgb(167, 158, 144); border-radius: 0.25rem; padding: 0.15rem 0.2rem; }
.document-header__title-input:focus-visible, .document-header__help summary:focus-visible { outline-offset: 2px; outline: rgb(30, 100, 210) solid 3px; }
.document-header__actions, .document-header__recovery { flex-wrap: wrap; gap: 0.35rem; display: flex; }
.document-header__actions { flex-shrink: 0; justify-content: flex-end; max-width: 100%; }
.chant-editor .document-header__actions select, .chant-editor .document-header__actions button, .chant-editor .document-header__recovery button { min-height: 2rem; padding: 0.25rem 0.55rem; font-size: 0.875rem; }
.document-header__meta { color: rgb(103, 95, 85); flex-wrap: wrap; align-items: baseline; gap: 0.25rem 1rem; margin-top: 0.2rem; font-size: 0.8rem; display: flex; }
.document-header__save-status { overflow-wrap: anywhere; margin: 0px; }
.document-header__save-status--unsaved, .document-header__error { color: rgb(139, 50, 30); }
.document-header__help summary { cursor: pointer; }
.document-header__help[open] { flex-basis: 100%; }
.document-header__help p { max-width: 40rem; margin: 0.4rem 0px; line-height: 1.45; }
.document-header__recovery { margin-top: 0.5rem; }
.document-header__recovery button { overflow-wrap: anywhere; }
.document-header__error { overflow-wrap: anywhere; margin: 0.4rem 0px 0px; font-size: 0.875rem; }
@media (width <= 32rem) {
  .document-header__main { flex-wrap: wrap; }
  .document-header__identity { flex-basis: 100%; }
  .document-header__actions { margin-left: auto; }
}
.lyric-alignment-controls label { align-items: baseline; gap: 0.25rem; margin: 0.25rem 0.75rem 0.25rem 0px; display: inline-flex; }
.preview-notice { color: rgb(103, 95, 85); text-align: center; width: min(56rem, 100% - 2rem); margin: 1rem auto 0px; font-size: 0.875rem; }
.chant-editor { width: min(56rem, 100% - 2rem); margin: 0px auto; padding: 1.5rem 0px; }
.chant-editor h1 { color: rgb(40, 35, 30); text-align: center; margin: 0px 0px 1rem; font-size: clamp(1.5rem, 5vw, 2rem); font-weight: 500; }
.neume-palette { grid-template-columns: repeat(10, minmax(0px, 1fr)); gap: 0.35rem; margin-bottom: 0.75rem; display: grid; }
.chant-editor button, .editor-actions input, .editor-actions select { color: rgb(40, 35, 30); min-width: 0px; min-height: 2.5rem; font: inherit; background: rgb(255, 253, 248); border: 1px solid rgb(167, 158, 144); border-radius: 0.25rem; padding: 0.4rem 0.5rem; }
.chant-editor button { cursor: pointer; }
.neume-palette button[aria-pressed="true"] { color: rgb(255, 255, 255); background: rgb(30, 100, 210); border-color: rgb(30, 100, 210); }
.chant-editor button:focus-visible, .editor-actions input:focus-visible, .editor-actions select:focus-visible, .editor-help summary:focus-visible { outline-offset: 2px; outline: rgb(30, 100, 210) solid 3px; }
.chant-editor button:disabled, .editor-actions input:disabled, .editor-actions select:disabled { color: rgb(113, 105, 95); opacity: 0.65; cursor: default; }
.editor-actions { flex-wrap: wrap; align-items: end; gap: 0.5rem; font-size: 0.875rem; display: flex; }
.editor-actions label, .editor-lyric { flex-direction: column; gap: 0.15rem; min-width: 0px; display: flex; }
.editor-actions label:has(select) { flex: 1 1 7rem; max-width: 12rem; }
.editor-actions select { width: 100%; }
.editor-lyric { flex: 1 1 8rem; }
.editor-lyric input { box-sizing: border-box; width: 100%; }
.editor-help { margin: 0.5rem 0px 0.75rem; font-size: 0.8rem; }
.editor-help summary { cursor: pointer; width: fit-content; }
.editor-help p { max-width: 48rem; line-height: 1.5; }
kbd { font: inherit; }
.editor-insert kbd { color: rgb(103, 95, 85); margin-left: 0.3rem; font-size: 0.75rem; }
@media (width <= 48rem) {
  .neume-palette { grid-template-columns: repeat(4, minmax(0px, 1fr)); }
}
@media (width <= 22rem) {
  .neume-palette { grid-template-columns: repeat(3, minmax(0px, 1fr)); }
}
.score { color: rgb(32, 29, 25); background: rgb(255, 253, 248); border: 1px solid rgb(216, 209, 197); border-radius: 0.25rem; width: 100%; height: auto; display: block; }
.score--placing { cursor: crosshair; }
.score__staff-line { stroke: currentcolor; stroke-width: 1.5px; vector-effect: non-scaling-stroke; }
.score__lyric { fill: currentcolor; font-family: Georgia, "Times New Roman", serif; }
.score__note { cursor: pointer; outline: none; }
.score__note-hit-target { fill: rgba(0, 0, 0, 0); }
.score__note:focus-visible .score__note-hit-target { fill: rgba(30, 100, 210, 0.15); stroke: rgb(30, 100, 210); stroke-width: 3px; vector-effect: non-scaling-stroke; }
.score__ink { fill: currentcolor; }
.score__neume-selection { fill: rgba(126, 73, 163, 0.08); stroke: rgb(126, 73, 163); stroke-dasharray: 5, 3; stroke-width: 2.5px; vector-effect: non-scaling-stroke; }
.score__placement-preview { color: rgb(30, 100, 210); pointer-events: none; }
.score__placement-ghost { opacity: 0.6; }
.score__placement-ghost .score__ink { stroke: rgb(255, 253, 248); stroke-width: 1.5px; paint-order: stroke; }
.score__placement-caret { stroke: currentcolor; stroke-width: 1.5px; stroke-dasharray: 4, 3; opacity: 0.8; }
.score__placement-caret line, .score__placement-caret path { vector-effect: non-scaling-stroke; }
.score__placement-target { fill: currentcolor; font: 12px system-ui, sans-serif; }
.score__note-selection { fill: none; stroke: rgb(194, 47, 38); stroke-width: 2.5px; vector-effect: non-scaling-stroke; }
.score--placing:focus { outline: none; }
.score__placement-context { fill: none; stroke: rgb(30, 100, 210); stroke-width: 2px; stroke-dasharray: 4, 3; vector-effect: non-scaling-stroke; display: none; }
.score--placing:focus .score__placement-context { display: block; }
.editor-announcement, .editor-sr-only { clip-path: inset(50%); white-space: nowrap; width: 1px; height: 1px; position: absolute; overflow: hidden; }
.syllable-controls { border: 1px solid rgb(216, 209, 197); border-radius: 0.25rem; margin: 0.75rem 0px; padding: 0.75rem; font-size: 0.875rem; }
.syllable-form { flex-wrap: wrap; align-items: center; gap: 0.5rem; display: flex; }
.syllable-form label { flex-basis: 100%; }
.syllable-form input { box-sizing: border-box; color: rgb(40, 35, 30); min-width: 0px; min-height: 2.5rem; font: inherit; background: rgb(255, 253, 248); border: 1px solid rgb(167, 158, 144); border-radius: 0.25rem; flex: 1 1 8rem; padding: 0.4rem 0.5rem; }
.syllable-form input:focus-visible { outline-offset: 2px; outline: rgb(30, 100, 210) solid 3px; }
.syllable-controls p { margin: 0.75rem 0px 0.35rem; }
.syllable-strip { gap: 0.35rem; padding: 0.25rem; display: flex; overflow-x: auto; }
.syllable-strip button { overflow-wrap: anywhere; flex: 0 0 auto; max-width: 14rem; }
.syllable-strip button[aria-pressed="true"] { background: rgb(231, 239, 252); border-color: rgb(30, 100, 210); }
.syllable-number { color: rgb(103, 95, 85); font-size: 0.75rem; }
.syllable-edit { border-top: 1px solid rgb(216, 209, 197); margin-top: 0.75rem; padding-top: 0.75rem; }
.score-workspace { position: relative; container-type: inline-size; }
.lyric-floating-entry { z-index: 1; background: rgb(255, 253, 248); border-radius: 0.25rem; width: min(13rem, 65%); position: absolute; }
.lyric-floating-entry input { width: 100%; }
.lyric-actions, .lyric-history-choice { flex-wrap: wrap; align-items: center; gap: 0.5rem; display: flex; }
.lyric-actions p, .lyric-history-choice p { flex-basis: 100%; }
.lyric-actions select { min-height: 2.5rem; font: inherit; }
.score__lyric[role="button"] { cursor: pointer; }
.score__lyric-selection { fill: rgb(227, 209, 238); stroke: none; pointer-events: none; }
.score__lyric:focus { outline: none; }
.score__lyric-focus-cue { fill: rgb(30, 100, 210); font: 11px system-ui, sans-serif; display: none; }
.score__lyric-control:focus-within > .score__lyric-focus-cue { display: block; }
.lyric-keyboard-target { border-left: 3px solid rgb(30, 100, 210); padding-left: 0.5rem; }
.score__move-target { fill: rgba(16, 128, 82, 0.094); stroke: rgb(16, 128, 82); stroke-width: 2px; stroke-dasharray: 3, 3; }
.score__move-target--preview { fill: rgba(18, 104, 206, 0.133); stroke: rgb(18, 104, 206); stroke-width: 3px; stroke-dasharray: none; }
.score__move-caption { fill: rgb(24, 87, 68); font-size: 10px; }
.score__move-hit-target { cursor: pointer; }
.score-viewport { max-width: 100%; overflow-x: auto; }
.score-viewport:focus-visible { outline-offset: 2px; outline: rgb(40, 121, 184) solid 2px; }
.division-controls { flex-wrap: wrap; align-items: center; gap: 0.5rem; margin-block: 0.75rem; display: flex; }
.division-controls > div { flex-basis: 100%; }
.score__division-selection { fill: rgba(0, 0, 0, 0); stroke: rgba(0, 0, 0, 0); }
.score__division--selected .score__division-selection { fill: rgb(219, 234, 254); stroke: rgb(37, 99, 235); stroke-width: 1.5px; }
.score__division:focus { outline: none; }
.score__division:focus .score__division-target { stroke: rgb(168, 85, 247); stroke-width: 2px; stroke-dasharray: 3, 2; }
.score__clef-ink { fill: currentcolor; }
.score__clef-control { cursor: pointer; outline: none; }
.score__clef-control--selected .score__clef-target { fill: rgb(220, 236, 255); stroke: rgb(35, 95, 155); stroke-width: 1.5px; }
.score__clef-control:focus .score__clef-target { stroke: rgb(123, 63, 176); stroke-width: 2px; stroke-dasharray: 4, 3; }
.clef-dialog { z-index: 20; background: rgb(255, 253, 248); border: 2px solid rgb(68, 54, 92); width: min(34rem, 90vw); max-height: 70vh; padding: 1.5rem; position: fixed; inset: 20% auto auto 50%; overflow: auto; transform: translate(-50%); box-shadow: rgba(0, 0, 0, 0.4) 0px 0px 0px 100vmax; }
.score__custos { fill: currentcolor; }
.clef-context { background: rgb(243, 237, 248); border: 1px solid rgb(185, 166, 206); border-radius: 0.3rem; flex-wrap: wrap; align-items: center; gap: 0.4rem; margin-bottom: 0.5rem; padding: 0.5rem; display: flex; }
.clef-context label { align-items: center; gap: 0.3rem; display: flex; }
.clef-context select { font: inherit; min-height: 2.5rem; }
.clef-context__hint, .clef-placement-help { font-size: 0.875rem; }
.clef-placement-help { margin: 0.5rem 0px; }
.score__clef-ghost { fill: rgb(40, 107, 154); opacity: 0.5; }
.score__clef-draft-preview { fill: rgb(101, 52, 139); opacity: 0.65; }
.clef-insertion-behavior { min-width: 0px; margin: 0.5rem 0px; }
.clef-insertion-behavior label { align-items: baseline; gap: 0.35rem; margin-right: 1rem; display: inline-flex; }
.clef-insertion-behavior p { margin: 0.4rem 0px 0px; font-size: 0.875rem; }
.note-modifiers { min-width: 0px; margin: 0px 0px 0.5rem; padding: 0.35rem 0.65rem 0.5rem; }
.note-modifiers__target { white-space: nowrap; text-overflow: ellipsis; margin: 0px 0px 0.25rem; font-size: 0.875rem; overflow: hidden; }
.note-modifiers__controls { flex-wrap: wrap; gap: 0.25rem 0.75rem; display: flex; }
.note-modifiers__controls label { flex: 1 1 17rem; justify-content: space-between; align-items: center; gap: 0.25rem; min-width: 0px; display: flex; }
.note-modifiers__controls select { width: 9rem; min-width: 0px; }
.quilisma-figure { flex-wrap: wrap; align-items: center; gap: 0.4rem; margin-block: 0.5rem; display: flex; }
.note-form-error { color: rgb(123, 38, 21); border: 1px solid rgb(142, 52, 30); padding: 0.5rem; }
